/** "24 dec." — a dated exception, in the site's own language.
 *
 *  Parsed and formatted in UTC on purpose: the string is a CALENDAR day, so
 *  reading it in the viewer's timezone would render "23 dec." to anyone west of
 *  Greenwich. Falls back to the raw ISO string rather than throwing, so an
 *  imported oddity is shown as-is instead of blanking the row. */
export function specialDateText(date: string, lang: SiteLocale): string {
  const parsed = Date.parse(`${date}T00:00:00Z`);
  if (Number.isNaN(parsed)) return date;
  try {
    return new Intl.DateTimeFormat(lang, {
      day: "numeric",
      month: "short",
      timeZone: "UTC",
    }).format(parsed);
  } catch {
    return date;
  }
}

