/** The windows a day is actually open, once its breaks are cut out.
 *
 *  A day is stored as one span plus optional intra-day breaks, so a bistro that
 *  serves lunch 11–14 and dinner 17–22 is `11:00–22:00` with a break at
 *  `14:00–17:00`. The renderer used to print the raw span, which told a guest
 *  the place was open at three in the afternoon — and when generation instead
 *  kept only one of the two services, the published table said "Onsdag
 *  11:00–14:00" directly above the owner's own note "Middag ons–lör 17–22"
 *  (production journey C 2026-07-26, backlog 0989).
 *
 *  Returns `[]` for a closed day or an incomplete span. Breaks that fall outside
 *  the span, or that swallow it whole, are ignored rather than trusted. */
export function openWindows(day: {
  closed?: boolean;
  open?: string;
  close?: string;
  breaks?: readonly { start: string; end: string }[];
}): { open: string; close: string }[] {
  if (day.closed || !day.open || !day.close) return [];
  if (day.close <= day.open) return [];
  const breaks = (day.breaks ?? [])
    .filter((b) => b.start && b.end && b.end > b.start)
    .filter((b) => b.end > day.open! && b.start < day.close!)
    .sort((a, b) => a.start.localeCompare(b.start));

  const windows: { open: string; close: string }[] = [];
  let cursor = day.open;
  for (const b of breaks) {
    const start = b.start > cursor ? b.start : cursor;
    if (start > cursor) windows.push({ open: cursor, close: start });
    if (b.end > cursor) cursor = b.end;
  }
  if (cursor < day.close) windows.push({ open: cursor, close: day.close });
  return windows;
}

/** Collapse the periods a listing reports for ONE weekday into the single span
 *  plus intra-day breaks that `openingDay` stores. The inverse of
 *  `openWindows`.
 *
 *  Google Places and schema.org both report a split day as TWO periods (lunch
 *  11–14, dinner 17–22). Every importer we have kept only the first and threw
 *  the rest away, so a bistro's dinner service never reached the site at all:
 *  the published table read "11:00–14:00" directly above the owner's own note
 *  "Middag ons–lör 17–22" (backlog 0989). One span 11:00–22:00 with a
 *  14:00–17:00 break says the same thing in the shape the model already has.
 *
 *  Overlapping and touching periods merge. Returns null when there is nothing
 *  usable. A day whose only period we cannot make sense of — an overnight
 *  18:00–02:00, which both sources split across two calendar days — is passed
 *  through untouched rather than dropped, so this never loses a day the old
 *  first-period-wins rule would have kept. */
export function spanWithBreaks(
  periods: readonly { open: string; close: string }[],
): {
  open: string;
  close: string;
  breaks?: { start: string; end: string }[];
} | null {
  const valid = periods
    .filter((p) => p.open && p.close && p.close > p.open)
    .sort((a, b) => a.open.localeCompare(b.open));
  if (valid.length === 0) {
    const first = periods.find((p) => p.open && p.close);
    return first ? { open: first.open, close: first.close } : null;
  }

  const merged: { open: string; close: string }[] = [];
  for (const p of valid) {
    const last = merged[merged.length - 1];
    // `<=` so two touching periods (…14:00 + 14:00…) become one span with no
    // zero-length break between them.
    if (last && p.open <= last.close) {
      if (p.close > last.close) last.close = p.close;
      continue;
    }
    merged.push({ open: p.open, close: p.close });
  }

  const breaks = merged
    .slice(0, -1)
    .map((w, i) => ({ start: w.close, end: merged[i + 1].open }));
  return {
    open: merged[0].open,
    close: merged[merged.length - 1].close,
    ...(breaks.length ? { breaks } : {}),
  };
}

const toMinutes = (hhmm: string): number => {
  const [h, m] = hhmm.split(":");
  return Number(h) * 60 + Number(m);
};

const toHhmm = (minutes: number): string =>
  `${String(Math.floor(minutes / 60)).padStart(2, "0")}:${String(minutes % 60).padStart(2, "0")}`;

/** The break to pre-fill when an owner adds one to a day: an hour in the middle
 *  of the span, snapped to the same 15-minute grid the editor's time selectors
 *  offer.
 *
 *  Placing it in the middle rather than at a fixed "12:00–13:00" matters: a
 *  break outside the day's span is ignored by `openWindows`, so a fixed default
 *  would do visibly nothing on a day that opens at 17:00 and the owner would
 *  have no idea why. Returns null when the day is too short to hold a break
 *  with opening time left on both sides — the caller hides the control. */
export function defaultBreak(
  open: string,
  close: string,
): { start: string; end: string } | null {
  const from = toMinutes(open);
  const to = toMinutes(close);
  if (!Number.isFinite(from) || !Number.isFinite(to)) return null;
  const length = 60;
  // 15 minutes of opening time on each side, so the break never swallows an end.
  if (to - from < length + 30) return null;
  const snapped = Math.round((from + to - length) / 2 / 15) * 15;
  const start = Math.min(Math.max(snapped, from + 15), to - 15 - length);
  return { start: toHhmm(start), end: toHhmm(start + length) };
}

/** "11:00–14:00, 17:00–22:00", or the closed label when the day has no window. */
export function hoursText(
  day: Parameters<typeof openWindows>[0],
  lang: SiteLocale,
): string {
  const windows = openWindows(day);
  if (windows.length === 0) return HOURS_STATUS_LABELS[lang].closed;
  return windows.map((w) => `${w.open}–${w.close}`).join(", ");
}
